    "question": "In McCabe's Cyclomatic Complexity, if a control flow graph has 14 edges and 10 nodes with 1 connected component, what is its complexity V(G)?",
    "options": [
      "4",
      "6",
      "8",
      "24"
    ],
    "answer": 1,
    "explanation": "V(G) = E - N + 2P = 14 - 10 + 2(1) = 6.",
